"""Gera o percurso e insere somente os complementos identificados por marcadores.
Os blocos Arduino sao lidos dos .ino entregues; nunca copiados manualmente.
"""
from pathlib import Path
from html import escape
import re
ROOT = Path(__file__).resolve().parents[2]
def write(path, text):
    p=ROOT/path; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(text,encoding='utf-8')
def figure(name,alt,caption):
    filename=name if '.' in name else name+'.svg'
    return f'<figure data-mbb-ampliavel="grafico" data-mbb-titulo="{escape(alt)}"><img src="../img/arduino/ventilador/{filename}" alt="{escape(alt)}" loading="lazy" decoding="async"><figcaption>{caption}</figcaption></figure>'
def table(head,rows):
    return '<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+c+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def code(folder):
    filename=folder+'.ino'; path=f'downloads/ventilador/{folder}/{filename}'; text=(ROOT/path).read_text(encoding='utf-8'); id='codigo-'+folder.split('_')[0]
    return f'<div class="vent-code"><div class="vent-code-head"><span>{filename}</span><a href="../{path}" download>Baixar .ino</a><button type="button" data-vent-copiar="{id}" aria-label="Copiar {filename}">Copiar</button></div><pre><code id="{id}">{escape(text)}</code></pre><span data-copia-estado role="status"></span></div>'
def checklist(group,title,items):
    return '<fieldset class="vent-checklist"><legend>'+title+'</legend>'+''.join(f'<label><input type="checkbox" data-vent-check="{group}-{i}"><span>{s}</span></label>' for i,s in enumerate(items))+'<small role="status">Marcações de estudo salvas somente neste navegador. Não certificam segurança.</small></fieldset>'
def checkpoint(question,answer):
    return f'<div class="vent-checkpoint"><h3>Checkpoint de aprendizagem</h3><p>{question}</p><details><summary>Conferir o raciocínio</summary><p>{answer}</p></details></div>'
def concept(path,anchor,label):
    return f'<a data-mbb-conceito href="{path}#{anchor}">{label}</a>'
def wrapper(n,title,obj,prior,body):
    prev=f'<a href="#etapa-{n-1}">← Etapa {n-1}</a>' if n>1 else '<a href="arduino.html#intro">Fundamentos do curso</a>'
    nxt=f'<a href="#etapa-{n+1}">Etapa {n+1} →</a>' if n<8 else '<a href="#topo">Rever o percurso ↑</a>'
    return f'<section id="etapa-{n}" class="vent-aula"><span class="vent-eyebrow">Etapa {n} de 8</span><h2>{title}</h2><div class="vent-meta"><p><strong>Ao terminar:</strong> {obj}</p><p><strong>Você já precisa saber:</strong> {prior}</p></div>{body}<nav class="vent-next" aria-label="Continuidade da etapa {n}">{prev}{nxt}</nav></section>'

reles='''<p>Um pino consegue fornecer um sinal de controle, mas não deve alimentar diretamente qualquer carga. A nova necessidade é separar <strong>quem dá a ordem</strong> de <strong>quem comuta a carga</strong>. Um relé eletromecânico faz isso com uma bobina e um conjunto de contatos.</p>
<p>Quando a bobina recebe a alimentação apropriada, seu campo magnético movimenta o contato. <strong>COM</strong> é o terminal comum; <strong>NA</strong> está normalmente aberto; <strong>NF</strong> está normalmente fechado. “Normalmente” significa bobina desenergizada. COM não é sinônimo de GND.</p>'''+figure('rele-contatos','Modelo conceitual da bobina e dos contatos COM, NA e NF.','Representação funcional ideal; não representa o circuito ou a posição dos bornes de um módulo específico.')+'''
<div class="vent-simulador"><h3>Experimente o contato ideal</h3><label><input type="checkbox" data-rele-toggle> Energizar a bobina no modelo</label><p data-rele-estado role="status">Bobina desenergizada: COM–NF fechado; COM–NA aberto (modelo ideal).</p><p>O modelo não reproduz arco, repique, atraso ou contato colado. Ele ensina somente a relação entre bobina e contato.</p></div>
<h3>O relé solto e o módulo não são a mesma coisa</h3><p>A bobina exige um circuito de acionamento. Um módulo pode incluir transistor, diodo para a bobina de corrente contínua, indicadores e optoacoplador. Verifique o esquema: a presença desses componentes não informa, sozinha, a capacidade dos bornes, das trilhas ou do isolamento. Não alimente uma bobina diretamente por um GPIO.</p>
<h3>Antes da primeira montagem física</h3><ol><li>Identifique o modelo, a tensão e a corrente da bobina ou de VCC/JD-VCC, quando existentes.</li><li>Localize no documento do módulo os pinos de alimentação, entrada e os contatos.</li><li>Confira a tensão e a corrente exigidas da entrada de controle e se o acionamento ocorre em HIGH ou LOW.</li><li>Com toda a alimentação removida, o responsável pode conferir COM–NF e COM–NA com instrumento apropriado, sem conectar o ventilador.</li><li>Depois de aprovar módulo, fonte e driver, use como carga somente LED e resistor alimentados por fonte de bancada de baixa tensão adequada. Os contatos funcionam como uma chave no circuito do LED.</li></ol>
<p><strong>Pendência desta edição:</strong> o módulo real ainda não foi identificado. Por isso, não há pinagem de alimentação, driver, fonte ou sketch físico de relé aprovados. A experiência executável disponível agora é o modelo de contato e a bancada com LEDs.</p>
<h3>Por que “10 A” não resolve a seleção?</h3><p>A capacidade de um contato depende da tensão, do tipo de carga, da partida, da frequência de manobra e das condições reais. Um motor não se comporta como uma resistência. Um contato pode colar: mandar desligar sua bobina não garante que ele abra. Um programa que escolhe uma saída por vez também não comprova que somente um caminho físico está fechado.</p>
<p>Para três velocidades de um motor, o projeto de potência precisa impedir combinações incompatíveis independentemente do software, inclusive nas falhas consideradas pelo responsável técnico. Não extrapole o modelo ideal para essa finalidade.</p>
<h3>Erro comum</h3><p>Inverter NA e NF muda o comportamento em repouso. Trocar o programa para “compensar” sem entender o contato pode produzir partida inesperada ao desligar o Arduino.</p>'''+checkpoint('Com a bobina desligada, um LED continua aceso. Isso prova defeito?','Não. Ele pode estar ligado ao contato NF. Identifique o caminho elétrico e o modelo antes de concluir. O experimento não envolve a rede elétrica.')+'''<p><a href="#p9">Continuar pelo curso: servo motor</a></p>'''

hc='''<p>No exemplo com ESP32, o Bluetooth está integrado à placa. No Uno precisamos acrescentar uma interface. O HC-05 faz a ponte entre <strong>Bluetooth Classic com perfil serial SPP</strong> e a comunicação serial UART. Ele não é um módulo BLE.</p>
<p>UART transmite uma sequência de bits entre TX e RX. TX de um dispositivo deve chegar ao RX do outro. Na conexão proposta para o software desta bancada, o Uno usa D2 como recepção e D3 como transmissão; os pinos 0 e 1 ficam livres para a USB.</p>'''+figure('hc05-interface','Mapa condicional de TX e RX entre Uno e HC-05, incluindo adaptação de nível.','Mapa lógico, não montagem liberada: alimentação, níveis e adaptação dependem da variante concreta do módulo.')+'''
<h3>Identificar vem antes de alimentar</h3><p>“HC-05” não identifica toda a placa adaptadora. Um regulador em VCC não comprova tolerância de RX a 5 V. Fotografe ou registre a serigrafia, localize o documento da variante e confirme VCC, GND, TX, RX e, se existentes, KEY/EN e STATE. Não conecte um pino apenas pela posição em uma foto de outro módulo.</p>
<p>O firmware entregue usa <code>SoftwareSerial(2, 3)</code> e 9600 bit/s em modo de dados. Esse é o perfil exigido pelo programa, que precisa ser conferido no HC-05 real. O modo de comandos AT pode usar outra configuração. Não altere configurações por tentativa.</p>
<h3>Três resultados diferentes</h3><ol><li><strong>Pareado:</strong> o Android reconheceu e associou o dispositivo.</li><li><strong>Conectado:</strong> o aplicativo abriu um enlace SPP.</li><li><strong>Comando confirmado:</strong> o Arduino recebeu a mensagem e respondeu. Ainda não é uma medição física do motor.</li></ol>
<h3>Teste depois da identificação</h3><p>Primeiro confirme a bancada de LEDs pelo Monitor Serial. Depois, com a alimentação desligada, monte somente a interface de baixa tensão conferida pelo responsável. Grave o checkpoint Bluetooth, pareie pelo Android e envie os caracteres de texto <code>0</code>, <code>1</code>, <code>2</code> e <code>3</code>.</p>
<p>Se não houver resposta, confira baud rate, TX/RX, referência elétrica e o modo do módulo. Não aumente a tensão. Não suponha PIN universal de pareamento. O LED do módulo e o pino STATE só podem ser interpretados conforme sua documentação.</p>'''+checkpoint('O celular diz “pareado”, mas o LED de bancada não muda. Qual teste separa comunicação e saída?','Comprove primeiro a bancada pelo checkpoint USB. Depois confira a abertura SPP no app, o texto enviado e o caractere de confirmação do Arduino.')+'''<p><a href="#b6-2">Continuar pelo curso: Wi-Fi com ESP32</a></p>'''

seg='''<p>Uma falha de dados pode virar uma ação física quando controlamos um equipamento. Antes de falar em 220 V, precisamos distinguir o circuito que aprendemos a programar da instalação que pode produzir choque, aquecimento ou movimento inesperado.</p>'''+figure('fronteira-seguranca','Separação entre bancada com LEDs e etapa profissional de 220 volts.','Fronteira de responsabilidade. Esta figura não contém um circuito de potência nem autoriza sua montagem.')+'''
<h3>Grandezas que mudam a decisão</h3>'''+table(['Conceito','O que significa no projeto'],[
('Tensão, corrente e resistência','Tensão é diferença de potencial; corrente é fluxo de carga; resistência limita esse fluxo. Reutilize o estudo dos LEDs e da Lei de Ohm antes de avançar.'),
('Corrente contínua e alternada','Na bancada USB trabalhamos com corrente contínua. A rede do ventilador é alternada; polaridade e formas de proteção não podem ser transportadas de um circuito para o outro.'),
('Potência','Em carga resistiva contínua, P = V × I. Em motor de corrente alternada, potência ativa, corrente e fator de potência precisam ser considerados; não dimensione tudo dividindo os watts por 220.'),
('Rede de 220 V','Pode ser fase–fase ou fase–neutro, conforme a instalação. Tensão nominal não identifica os condutores. Neutro não substitui o condutor de proteção, PE.'),
('Choque e fuga','Uma corrente pelo corpo pode causar lesão grave. Isolação, invólucro, proteção e procedimentos precisam atuar em conjunto. Uma carcaça ou fio aparentemente inofensivo pode estar energizado.'),
('Curto e sobrecarga','Curto cria um caminho de impedância muito baixa; sobrecarga pode aquecer condutores sem curto. Disjuntor e fusível precisam ser coordenados com o circuito.'),
('DR','Dispositivo diferencial residual detecta desequilíbrio entre as correntes dos condutores monitorados. Não substitui proteção contra sobrecorrente, isolamento ou todos os cuidados contra choque.'),
('Motor e capacitor','A partida e a comutação podem exigir mais dos contatos. Capacitores podem reter energia após desligar. Sua condição e descarga são tarefas do responsável, não experiências de tentativa.'),
('Isolamento e separação','Um componente com isolação não comprova isolação do sistema inteiro. Fonte, placa, trilhas, bornes, distâncias, cabos e invólucro entram na avaliação.'),
('Desligar e desenergizar','O botão do aplicativo solicita parada. A desenergização para intervenção exige procedimentos e verificação compatíveis com a instalação; não se resume ao estado de um LED.')])+'''
<h3>Regras da bancada</h3><p>Use somente fonte de baixa tensão adequada e a montagem de LEDs verificada. Não introduza rede elétrica em protoboards, jumpers, USB, pinos do Arduino ou bornes não avaliados. Não abra o ventilador para descobrir fios pelo funcionamento. Mantenha hélice, grade, cabos e base íntegros.</p>
<h3>Critérios para a etapa profissional</h3><p>O responsável precisa identificar o motor e suas velocidades, conservar as proteções originais pertinentes, dimensionar manobra e proteção, definir intertravamento, invólucro e desconexão física, avaliar aterramento conforme a classe do aparelho e executar os ensaios necessários. Ter um motor funcionando não comprova segurança.</p>
<h3>Referências e vigência</h3><p>Na consulta de 19/10/2026, a página oficial do MTE informa a NR-10 atualizada em 2019 vigente até 31/05/2027 e a nova redação da Portaria nº 737/2026 com vigência em 01/06/2027, ressalvado o prazo específico previsto para instalações existentes. Para instalações de baixa tensão, consulte a NBR 5410 no catálogo ABNT e confira a edição aplicável. O Inmetro apresenta a Portaria nº 299/2021 para os ventiladores domésticos abrangidos. A regulamentação consolidada, suas alterações e a aplicabilidade ao equipamento modificado precisam de conferência profissional. Esta aula não declara conformidade.</p>
<ul><li><a href="https://www.gov.br/trabalho-e-emprego/pt-br/acesso-a-informacao/participacao-social/conselhos-e-orgaos-colegiados/comissao-tripartite-partitaria-permanente/normas-regulamentadora/normas-regulamentadoras-vigentes/norma-regulamentadora-no-10-nr-10">MTE — NR-10 e textos oficiais</a></li><li><a href="https://abntcatalogo.com.br/">ABNT — catálogo de normas</a></li><li><a href="https://www.gov.br/inmetro/pt-br/acesso-a-informacao/perguntas-frequentes/avaliacao-da-conformidade/ventiladores-de-mesa/ventiladores-estao-regulamentados-pelo-inmetro">Inmetro — regulamentação de ventiladores</a></li><li><a href="https://www.ia.omron.com/product/cautions/36/safety_precautions.html">Omron — seleção e limitações de relés</a></li></ul>'''+checklist('tecnica','Verificação técnica — pendências, não liberação',[
'Identifiquei o ventilador e registrei placa, manual, tensão, potência e estado mecânico.',
'O responsável identificou motor, seletor, capacitor e proteção térmica.',
'Relés e instalação têm dimensionamento específico e análise de contato colado.',
'Há prevenção independente de velocidades incompatíveis e de religamento inesperado.',
'Fonte, separação elétrica, invólucro, cabos e desconexão física foram avaliados.',
'As inspeções e os ensaios foram documentados pelo responsável competente.'])+checkpoint('Todas as caixas estão marcadas. Isso permite energizar a montagem?','Não. O checklist organiza evidências; não substitui projeto, inspeção, responsabilidade profissional ou autorização de energização.')+'''<p><a href="#b9-2">Continuar pelo curso: segurança de sistemas e informações</a></p>'''

app='''<p>O Arduino já interpreta mensagens. Agora precisamos transformar toques em mensagens e mostrar o que realmente sabemos sobre o enlace. Você reutilizará Designer, eventos e testes; a novidade é o componente não visível <strong>BluetoothClient</strong>.</p>
<div class="vent-alerta"><strong>Aplicativo 0.3: use o checkpoint 3.</strong> Grave <code>03_bancada_supervisionada.ino</code> antes de conectar este aplicativo à bancada de LEDs. Ele envia <code>?</code> a cada 500 ms. O checkpoint 2 trata esse caractere como inválido e apaga os LEDs; use-o somente no exercício anterior de mensagens, sem heartbeat. Confira no relatório os resultados de importação, compilação e download desta revisão. Importar ou compilar não comprova execução Android nem comunicação física.</div>
<h3>1. Prepare a tela no Designer</h3><p>Crie o projeto <code>VentiladorMBB</code>. Use “Ventilador MbB” em Screen1.Title, AppName e no texto da legenda Titulo. A identificação Android desta revisão é 0.3-experimental/code 3. Use orientação retrato, dimensionamento responsivo e rolagem habilitada. Acrescente os componentes com os nomes exatos abaixo; os blocos do arquivo usam esses nomes.</p>'''+table(['Componente','Nome','Configuração'],[
('Label','Titulo','Texto: Ventilador MbB; fonte 22, negrito.'),('ListPicker','Conectar','Texto: Conectar ao HC-05; largura: preencher.'),('Label','Estado','Texto inicial: Desconectado. Sem confirmação física.'),('Button','Velocidade1','Texto: Velocidade 1; Enabled: falso; largura: preencher.'),('Button','Velocidade2','Texto: Velocidade 2; Enabled: falso; largura: preencher.'),('Button','Velocidade3','Texto: Velocidade 3; Enabled: falso; largura: preencher.'),('Button','Desligar','Texto: Desligar; Enabled: falso; largura: preencher.'),('Label','Aviso','Texto: Protótipo somente com LEDs. Desligar no app não isola energia.'),('BluetoothClient','BluetoothClient1','Secure: verdadeiro; DisconnectOnError: verdadeiro; NoLocationNeeded: verdadeiro.'),('Clock','Clock1','TimerInterval: 500; TimerEnabled: verdadeiro; TimerAlwaysFires: falso.')])+'''
<h3>2. Guarde o estado entre os eventos</h3><p>Crie cinco variáveis globais: <code>recebido</code>, iniciada com texto vazio, e <code>conectadoAntes</code>, iniciada como falso. Essas duas guardam o byte recebido e detectam a desconexão sem apagar a mensagem específica de erro. Acrescente <code>aguardando</code> (falso), <code>esperado</code> (texto vazio) e <code>prazoConfirmacao</code> (zero): indicam uma resposta pendente, o caractere esperado e o instante limite em milissegundos.</p><p>Por exemplo: ao tocar em velocidade 2, <code>esperado</code> guarda o texto “2” e <code>aguardando</code> fica verdadeiro. Uma resposta “1” não confirma esse pedido. O relógio define até quando aguardar; ele não mede o giro de um motor.</p>
<h3>3. Construa os procedimentos antes de usá-los</h3><p>Vários eventos precisam bloquear botões, limpar uma espera e informar falhas. Repetir esses blocos em cada evento torna a revisão difícil. Na gaveta <strong>Procedimentos</strong>, crie um procedimento “fazer”, dê um nome e use o mutador para acrescentar as entradas indicadas. Uma entrada vale somente dentro daquele procedimento; as cinco globais continuam guardando o estado entre eventos.</p>'''+table(['Procedimento','Entrada','Blocos e ordem'],[('DefinirComandos','ativo: verdadeiro/falso','Defina Enabled dos quatro botões com o valor ativo.'),('LimparEspera','nenhuma','aguardando=falso; esperado=texto vazio; prazoConfirmacao=0.'),('EncerrarEnlace','mensagem: texto','LimparEspera; conectadoAntes=falso; DefinirComandos(falso); Estado.Text=mensagem; desconectar se conectado.'),('EnviarComando','comando: texto','esperado=comando; aguardando=verdadeiro; prazoConfirmacao=Clock1.SystemTime()+2000; DefinirComandos(falso); Desligar.Enabled=verdadeiro; atualizar Estado; SendText(comando) por último.'),('ProcessarResposta','resposta: texto já validado','Se aguardando, só a resposta esperada limpa a espera e libera botões. Outra resposta válida informa espera sem renovar o prazo; sem espera, informa estado lógico.')])+'''<ol><li>Construa <code>DefinirComandos(ativo)</code> e <code>LimparEspera()</code>. Teste suas responsabilidades antes de usá-los em outros procedimentos.</li><li>Monte <code>EncerrarEnlace(mensagem)</code>: limpe a espera, zere conectadoAntes, bloqueie os quatro botões, mostre mensagem e desconecte se ainda conectado. Chame-o em Screen1.Initialize com a mensagem inicial.</li><li>Monte <code>EnviarComando(comando)</code> na ordem indicada. Sua entrada recebe um texto, como “2”; a variável global <code>esperado</code> guarda esse valor depois que o procedimento termina. Deixe <code>SendText(comando)</code> por último: se o envio disparar um erro, a mensagem de falha não será substituída pela mensagem de espera.</li><li>Monte <code>ProcessarResposta(resposta)</code>. Se <code>aguardando</code> for verdadeiro e <code>resposta = esperado</code>, chame <code>LimparEspera()</code>, depois <code>DefinirComandos(verdadeiro)</code> e mostre “Confirmação lógica recebida: ” com a resposta. Uma resposta válida diferente só informa que ainda há espera. Sem espera pendente, informe o estado lógico recebido. O Timer validará o byte antes de chamar este procedimento.</li></ol><p>Os procedimentos do arquivo têm comentários sobre essas responsabilidades. A organização em colunas separa conexão, comandos/supervisão e procedimentos; as figuras conceituais não substituem os blocos reais.</p><h3>4. Liste os aparelhos e confirme a conexão</h3><ol><li>Em <code>Conectar.BeforePicking</code>, comece atribuindo uma lista vazia a <code>Conectar.Elements</code>. Isso remove aparelhos de uma consulta anterior. Confira <code>BluetoothClient1.Available</code> e <code>Enabled</code>; somente se ambos forem verdadeiros atribua <code>AddressesAndNames</code> a <code>Conectar.Elements</code>. Caso contrário, informe se o Bluetooth está indisponível ou desligado.</li><li>Em <code>Conectar.AfterPicking</code>, primeiro chame <code>EncerrarEnlace("Conectando; estado físico não verificado.")</code>. Em seguida, teste o resultado de <code>Connect(Conectar.Selection)</code>. Se verdadeiro, defina <code>conectadoAntes</code> como verdadeiro e chame <code>EnviarComando("0")</code>. Se falso, chame <code>EncerrarEnlace</code> com a mensagem de falha.</li><li>Essa primeira troca de “0” é a confirmação inicial, chamada <em>handshake</em>. Até receber “0” dentro do prazo, velocidades ficam bloqueadas e somente Desligar permanece disponível. Parear e conectar, sozinhos, não liberam as velocidades.</li></ol>
<h3>5. Ligue os cliques aos procedimentos</h3><p>Nos eventos <code>Velocidade1.Click</code>, <code>Velocidade2.Click</code> e <code>Velocidade3.Click</code>, teste primeiro <code>IsConnected</code>. Se falso, chame <code>EncerrarEnlace</code> com a mensagem de desconexão. Se verdadeiro e <code>aguardando = falso</code>, chame <code>EnviarComando</code> com o bloco de texto “1”, “2” ou “3”, respectivamente. Durante uma espera, ignore novos cliques de velocidade.</p><p>Os três cliques chamam <code>EnviarComando</code>; não duplique neles sua preparação nem acrescente outro <code>SendText</code>. É o procedimento que prepara a espera e envia o caractere. Não use <code>Send1ByteNumber</code>: o valor binário 1 é diferente do caractere de texto “1” esperado pelo Arduino. Escolher a velocidade já seleciona o estado; não há outro comando para ligar.</p><p><strong>Desligar tem um caminho próprio.</strong> Em <code>Desligar.Click</code>, confira a conexão. Se não estiver conectado, chame <code>EncerrarEnlace</code>. Se conectado, siga os casos abaixo na ordem:</p><ol><li>Sem confirmação pendente: chame <code>EnviarComando("0")</code>.</li><li>Aguardando “1”, “2” ou “3”: chame <code>EnviarComando("0")</code>. O pedido de parada passa a ter sua própria espera, com prioridade sobre a velocidade.</li><li>Já aguardando “0”: compare <code>Clock1.SystemTime()</code> com <code>prazoConfirmacao</code>. Se o prazo venceu, chame <code>EncerrarEnlace</code> com a mensagem de ausência de confirmação, sem reenviar. Se ainda não venceu, use somente <code>BluetoothClient1.SendText("0")</code>. Não altere a espera ou o prazo e não chame <code>EnviarComando</code> nesse reenvio.</li></ol><p>Exemplo de tempo: se o primeiro “0” foi preparado quando SystemTime valia 1000 ms, o prazo será 3000 ms. Repetir Desligar em 1400 ou 1800 ms reenvia “0”, mas mantém 3000 ms. Uma resposta antiga “3” também não muda esse prazo. Esses valores ilustram a comparação; a execução depende do relógio e do agendamento do Android.</p>
<h3>6. Supervisione a comunicação</h3><p>O Clock é utilizado internamente para comunicação, sem acrescentar um temporizador de uso ao ventilador. A cada evento Timer, se houver conexão, confira primeiro se uma confirmação pendente expirou: <code>Clock1.SystemTime() &gt;= prazoConfirmacao</code>. Nesse caso, encerre o enlace, limpe a espera e bloqueie todos os comandos. Só se ainda conectado envie <code>SendText("?")</code>. Esse caractere renova a supervisão do checkpoint 3; não seleciona velocidade. Após o envio, confira novamente <code>IsConnected</code> antes de consultar ou ler a recepção: um erro de envio pode ter encerrado o enlace. Essa verificação também existe depois do tratamento do prazo.</p><p>Se <code>BytesAvailableToReceive()</code> for maior que zero, leia <code>ReceiveText(1)</code>. Os retornos válidos são caracteres “0”, “1”, “2” ou “3”: para cada um, chame <code>ProcessarResposta(recebido)</code>. Durante uma espera, só o caractere esperado libera as velocidades e mostra “Confirmação lógica recebida: …”. Outro estado válido é informado como resposta anterior, sem renovar o prazo. Sem espera, informe “Estado lógico recebido: …”. Um byte inválido encerra o enlace. Ler um byte disponível evita bloquear esperando um delimitador inexistente. O app lê no máximo um byte por ciclo. O bloqueio das velocidades reduz o acúmulo; “Desligar” pode antecipar uma resposta anterior. O protocolo simples não possui identificador de mensagem: não autentica respostas nem distingue respostas antigas com o mesmo caractere.</p><p>Se <code>IsConnected</code> for falso, chame <code>DefinirComandos(falso)</code> e <code>LimparEspera()</code>. Somente se <code>conectadoAntes</code> ainda for verdadeiro, defina-o como falso e mostre “Desconectado. Estado físico não verificado”. Se já era falso, preserve a mensagem existente: ela pode explicar um erro mais específico. Se o app parar de enviar supervisão, os LEDs do checkpoint 3 apagam após o prazo de bancada. Não reaplique automaticamente a última velocidade.</p><p>O prazo de confirmação é conferido no próximo Timer executado; não é garantia de reação Android em exatamente 2 s. SystemTime acompanha o relógio do aparelho, que pode ser ajustado. “?” não recebe eco nos sketches atuais: sem comando pendente, o aplicativo não detecta sozinho uma interrupção exclusiva do caminho de retorno. Estes são limites didáticos documentados, não recursos de segurança de potência.</p>
<h3>7. Trate permissões e erros</h3><p>No Android 12 ou posterior, a documentação do MIT informa permissões BLUETOOTH_CONNECT e BLUETOOTH_SCAN para listar os aparelhos pareados. Em <code>Screen1.PermissionDenied</code> e <code>Screen1.ErrorOccurred</code>, chame <code>EncerrarEnlace(mensagem)</code> com a explicação correspondente. O procedimento limpa a espera, bloqueia os comandos, preserva a explicação e desconecta o cliente quando ainda há enlace. Não entre em um ciclo de pedidos de permissão. O projeto não faz descoberta contínua nem pede localização para rastrear o aluno.</p>'''+figure('app-eventos','Mapa dos eventos e mensagens usados no projeto App Inventor.','Mapa de eventos correspondente ao .aia. Esta figura continua sendo um mapa conceitual, não uma captura. A importação real e a comparação dos blocos reexportados estão registradas no relatório; o mapa não substitui essa evidência.')+'''
<h3>8. Baixe e teste o aplicativo</h3><p><a class="vent-download" href="../downloads/ventilador/VentiladorMBB03.apk" download>Baixar aplicativo Android (.apk) — bancada experimental</a> · <a href="../downloads/ventilador/APK_VERIFICADO.md" download>Versão, hash e verificações do APK</a></p><p>O APK foi compilado no MIT e recebido do professor; integridade, versão e assinaturas foram verificadas. Instalação, execução Android e Bluetooth físico continuam pendentes. Para examinar ou modificar os blocos, use o projeto editável abaixo.</p><p><a class="vent-download" href="../downloads/ventilador/VentiladorMBB.aia" download>Baixar VentiladorMBB.aia — experimental</a> · <a href="../downloads/ventilador/appinventor/Screen1.bky" download>Inspecionar XML dos blocos</a> · <a href="../downloads/ventilador/appinventor/Screen1.scm" download>Inspecionar configuração do Designer</a> · <a href="../downloads/ventilador/VALIDACAO_MANUAL.md" download>Roteiro de validação manual</a></p><ol><li>Importe o .aia no App Inventor e verifique se não há blocos desconhecidos ou desconectados.</li><li>Compare os nomes do Designer com a tabela.</li><li>Teste no Companion e depois compile um APK pelo menu Build do editor.</li><li>Instale esse APK em um Android de teste e repita conexão, permissão negada, comandos, queda de comunicação e reconexão.</li><li>Registre aparelho, Android, versão do editor, HC-05 e resultados. Só então valide a entrega instalável.</li></ol>
<p><a href="https://ai2.appinventor.mit.edu/reference/components/connectivity.html#BluetoothClient">MIT — BluetoothClient</a> · <a href="https://developer.android.com/develop/connectivity/bluetooth/bt-permissions">Android — permissões Bluetooth</a></p>'''+checkpoint('Um retorno “2” chegou. O texto correto é “motor girando na velocidade 2”?','Não. O retorno confirma o estado lógico aplicado pelo programa da bancada. Não existe sensor de rotação nem verificação física dos contatos ou do motor.')+figure('app-designer-mit.jpg','Captura real do Designer MIT: Ventilador MbB, revisão 0.3.','Captura real do Designer do projeto VentiladorMBB03; não é execução Android. Título da tela e legenda Titulo padronizados.')+figure('app-blocos-mit.jpg','Captura real dos blocos do evento Velocidade1 no MIT.','Blocos reais importados: só enviar velocidade quando conectado e sem espera; reutilizar EnviarComando e EncerrarEnlace. A imagem mostra um recorte, não o aplicativo completo.')+'''<p><a href="#publicacao-app">Continuar pelo curso: compilação e publicação de aplicativos</a></p>'''

titles=['Conhecer o desafio','Eletricidade e segurança','Do comando ao contato do relé','Bluetooth com HC-05','Programar três estados e desligar','Construir o aplicativo Android','A fronteira com o ventilador real','Testar, explicar e concluir']
body1='''<p>Está calor e o seletor do ventilador fica longe. O problema parece ser apenas criar quatro botões no celular. Mas entre o toque e o motor existem comunicação, interpretação, acionamento e proteção. Vamos separar essas responsabilidades e produzir uma evidência simples em cada passo.</p><p><strong>Resultado desta versão:</strong> controlar três LEDs que representam as velocidades, construir o app Android e estudar a integração. O ventilador real de 220 V permanece como objetivo final condicionado ao projeto elétrico específico.</p>'''+table(['Parte','Função','O que comprova'],[('Aplicativo','Enviar um dos textos 0, 1, 2 ou 3','Uma intenção do usuário.'),('HC-05','Transportar mensagens por Bluetooth Classic/SPP','Comunicação, depois de testada.'),('Arduino Uno','Interpretar e selecionar uma saída lógica','Estado do programa.'),('LEDs de bancada','Representar baixa, média, alta e parada','A saída visual observada.'),('Relés e potência','Manobrar o equipamento real em projeto posterior','Exigem análise independente e ensaios.')])+'''
<h3>Separe a bancada</h3><p>Use Uno R3, cabo USB, três LEDs e três resistores de 330 Ω, protoboard e jumpers apenas na baixa tensão. Para a etapa sem fio, será necessário um HC-05 identificado, alimentação adequada à sua variante e adaptação de níveis validada. O módulo de relés e o ventilador não entram na montagem de LEDs.</p><p>Retome os fundamentos se ainda não consegue identificar o GND, a polaridade do LED ou o motivo do resistor. Nesta etapa, faça um desenho indicando quem envia a ordem e quem executa.</p>'''+checklist('aluno-inicio','Verificação do aluno',['Consigo explicar a função do celular, HC-05, Arduino e LEDs.','Separei a bancada da rede elétrica e do ventilador.','Sei que confirmação de comando não é medição do motor.'])+checkpoint('Onde se decide a velocidade: no HC-05 ou no Arduino?','O aplicativo envia a intenção. O HC-05 transporta a mensagem. O Arduino interpreta e seleciona o estado lógico. Um componente não substitui a função do outro.')
body2='''<p>O primeiro limite aparece antes da programação: um circuito com LEDs não é uma instalação de potência. Precisamos compreender por que valores elétricos, separação e comportamento nas falhas importam.</p><p>Estude o tópico oficial: '''+concept('arduino-seguranca.html','b9-eletricidade','Eletricidade e segurança no controle de equipamentos')+'''. Ele reúne os novos fundamentos, as proteções e os limites de responsabilidade, sem repetir toda a base de Lei de Ohm já apresentada no curso.</p>'''+figure('fronteira-seguranca','Bancada de baixa tensão separada da etapa profissional.','A fase experimental não contém ligações de potência.')+checklist('aluno-seguranca','Verificação do aluno — antes da bancada',['Diferencio desligamento pelo aplicativo e desenergização para manutenção.','Entendo que 220 V não identifica, sozinho, fase e neutro.','Sei que jumper e protoboard não recebem rede elétrica.','Não vou abrir, modificar ou energizar o ventilador nesta atividade.'])+checkpoint('Se o Arduino estiver desligado, podemos presumir que o motor está isolado da rede?','Não. A condição do controlador não comprova abertura dos contatos ou isolamento da alimentação. A desconexão e os procedimentos são independentes.')
body3='''<p>O pino do Uno não pode assumir a função do seletor de potência. Antes de acrescentar qualquer módulo, precisamos entender como uma bobina comanda contatos e quais falhas esse mecanismo pode apresentar.</p><p>Abra '''+concept('arduino.html','atuadores-reles','Relés: bobina, COM, NA, NF e limites da montagem')+'''. Experimente o modelo de contato e volte a esta etapa.</p><h3>Prática desta edição</h3><p>Use a simulação ideal para prever COM–NF e COM–NA. Registre o módulo disponível, sua documentação e os dados exigidos pela aula. A montagem e o código físico do relé aguardam essa identificação. Enquanto isso, avance com os três LEDs, sem adaptar o programa para potência.</p>'''+figure('rele-contatos','Bobina e contatos de um relé em modelo funcional.','O desenho é conceitual: não indica a posição dos terminais de um produto.')+checklist('aluno-rele','Verificação do aluno',['Expliquei o que significa “normalmente” em NA e NF.','Diferenciei entrada de controle, bobina e contatos.','Registrei que o módulo real ainda precisa de conferência antes de ser alimentado.'])+checkpoint('Por que apagar a saída do Arduino não garante que um contato abra?','Porque o acionamento elétrico e o contato são partes diferentes. Um contato pode estar colado. O circuito real precisa tratar as falhas relevantes de forma independente.')
body4='''<p>Depois de entender a saída, precisamos transportar a intenção do celular até o Uno. O curso já utiliza Bluetooth no ESP32; aqui o HC-05 supre uma interface que o Uno não possui.</p><p>Estude '''+concept('arduino-conectividade.html','b6-hc05','HC-05: serial, pareamento, níveis e identificação da variante')+'''. Sem documentação da variante, faça a leitura e a simulação; mantenha a montagem física sem o módulo.</p>'''+figure('hc05-interface','Interface lógica entre o Uno e o módulo Bluetooth.','D2 recebe e D3 transmite no software fornecido. A alimentação e a adaptação ainda dependem do módulo real.')+table(['Mensagem de texto','Estado solicitado'],[('0','Todos os indicadores apagados.'),('1','Somente LED de baixa aceso.'),('2','Somente LED de média aceso.'),('3','Somente LED de alta aceso.')])+'''<h3>Erro comum: texto e número binário</h3><p>O texto “1” é transmitido como o byte ASCII 49. Enviar o valor binário 1 não produz o mesmo dado. Nosso programa compara os caracteres <code>'0'</code> a <code>'3'</code>.</p>'''+checklist('aluno-bt','Verificação do aluno',['Diferenciei pareamento, conexão e confirmação.','Entendi o cruzamento lógico TX → RX.','Identifiquei quais informações faltam do HC-05 antes da montagem.'])+checkpoint('O que precisa ser revisto ao trocar apenas a placa adaptadora do HC-05?','Alimentação, níveis das entradas e saídas, pinagem, modo de dados, baud rate e significado dos indicadores. O nome HC-05 não resolve essas diferenças.')
body5='''<p>Antes de depender da comunicação sem fio, vamos provar que o Uno interpreta os quatro caracteres. A montagem abaixo contém somente LEDs. Cada resistor pertence ao seu LED; não use um único resistor compartilhado.</p>'''+figure('uno-leds','D5, D6 e D7 ligados individualmente a resistores de 330 ohms e LEDs com retorno ao GND.','Circuito de bancada usado pelos três checkpoints. Observe a polaridade dos LEDs e confirme a montagem antes do USB.')+table(['Saída do Uno','Caminho completo'],[('D5','Resistor 330 Ω → ânodo LED 1 → cátodo → GND.'),('D6','Resistor 330 Ω → ânodo LED 2 → cátodo → GND.'),('D7','Resistor 330 Ω → ânodo LED 3 → cátodo → GND.')])+'''
<h3>Checkpoint 1 — interpretar pelo USB</h3><ol><li>Com a placa desligada, monte os três caminhos e confira curto e polaridade.</li><li>Na IDE, selecione a placa Uno e a porta correta. Grave o arquivo completo abaixo.</li><li>Abra o Monitor Serial em 9600, sem fim de linha. Envie 1, depois 2, depois 3 e, por fim, 0.</li><li>Confira o LED correspondente e o caractere de retorno. Teste também uma letra inválida: o programa deve apagar os LEDs e responder 0.</li></ol>'''+code('01_serial_leds')+'''
<p><code>selecionar()</code> apaga primeiro os três LEDs e só então acende o escolhido. O índice <code>velocidade - 1</code> converte os estados 1, 2 e 3 para as posições 0, 1 e 2 do vetor. O estado zero não acende nenhum LED.</p>
<h3>Checkpoint 2 — mudar o transporte</h3><p>Apenas depois de validar a interface do HC-05, mantenha os LEDs e use o próximo programa. A interpretação não mudou; a leitura e a confirmação passaram de <code>Serial</code> para <code>bluetooth</code>. Ele ainda não supervisiona a ausência de mensagens. Use somente na bancada.</p>'''+code('02_bluetooth_leds')+'''
<h3>Checkpoint 3 — observar a falta de comunicação</h3><p>No programa anterior, o último estado permanecia mesmo sem novas mensagens. Agora o aplicativo envia “?” a cada 500 ms. Se passarem 2000 ms sem mensagem válida para a supervisão, o programa apaga os LEDs. Esses tempos foram escolhidos para uma demonstração perceptível; não dimensionam segurança de motor. “?” não liga a bancada, e uma supervisão atrasada não restaura a velocidade.</p>'''+code('03_bancada_supervisionada')+'''
<p>A subtração sem sinal permite verificar o intervalo mesmo na volta do contador <code>millis()</code>. Não usamos <code>delay()</code> nem esperamos uma linha completa para receber comandos. Os programas não são firmware de potência: não incluem detecção física de contato colado nem intertravamento elétrico.</p>
<h3>Experimente antes da bancada</h3><div class="vent-simulador" id="vent-simulador"><p>Simulação local de mensagens e LEDs. Não usa Bluetooth real nem controla equipamento.</p><div class="vent-sim-grid"><div><button type="button" data-sim-conectar>Conectar / desconectar modelo</button><div class="vent-controles"><button type="button" data-sim-comando="1">Velocidade 1</button><button type="button" data-sim-comando="2">Velocidade 2</button><button type="button" data-sim-comando="3">Velocidade 3</button><button type="button" data-sim-comando="0">Desligar</button></div><button type="button" data-sim-falha>Interromper supervisão</button><p class="vent-state" data-sim-estado role="status"></p></div><div><div class="vent-leds"><span class="vent-led" data-sim-led="1"><i aria-hidden="true"></i>Baixa</span><span class="vent-led" data-sim-led="2"><i aria-hidden="true"></i>Média</span><span class="vent-led" data-sim-led="3"><i aria-hidden="true"></i>Alta</span></div><pre class="vent-log" data-sim-log aria-label="Registro da simulação"></pre></div></div></div>
<h3>Teste de transições</h3><p>Teste todas as 12 trocas entre estados diferentes de 0 a 3, além das quatro repetições do mesmo comando. No checkpoint 3, acione um estado, interrompa a supervisão e confira a parada lógica. Volte a enviar somente “?”: os LEDs precisam continuar apagados até um novo comando de velocidade.</p>'''+checklist('aluno-codigo','Verificação da bancada de LEDs',['Conferi os três resistores e as polaridades antes do USB.','O checkpoint 1 responde a 0, 1, 2 e 3 e apaga com comando inválido.','Comparei o código exibido, copiado e baixado.','Entendo que os checkpoints 2 e 3 dependem da interface HC-05 verificada.','Separei os resultados simulados dos testes efetivamente feitos com a placa.'])+checkpoint('Por que não basta testar somente 0→1→2→3?','Porque transições no sentido contrário também podem revelar problemas de ordem. Teste cada par de estados. Na potência, isso ainda não comprovaria o comportamento dos contatos.')
body6='''<p>O transporte e o programa estão separados. Falta construir uma interface que envie o dado certo, indique o enlace e apresente a confirmação com honestidade.</p><p><a class="vent-download" href="../downloads/ventilador/VentiladorMBB03.apk" download>Baixar Ventilador MbB para Android (.apk)</a> · <a href="../downloads/ventilador/APK_VERIFICADO.md" download>Conferir versão e integridade</a></p><p>APK com integridade e assinaturas verificadas; testes no aparelho e na bancada ainda pendentes.</p><p>Siga a aula oficial '''+concept('appinventor.html','bluetooth-ventilador','Aplicativo de bancada Bluetooth no MIT App Inventor')+'''. Ela contém nomes de componentes, configurações do Designer, eventos, permissões e o projeto editável.</p><div class="vent-alerta"><strong>Antes de importar:</strong> este aplicativo com heartbeat exige o <code>checkpoint 3 — bancada supervisionada</code>. O checkpoint 2 não reconhece “?” e apaga os LEDs; preserve-o para o exercício anterior sem heartbeat.</div><div class="vent-app-preview" aria-label="Prévia estática da interface, sem comandos reais"><h3>Ventilador MbB</h3><p>Prévia visual · bancada de LEDs</p><button type="button" disabled>Conectar ao HC-05</button><p>Desconectado. Sem confirmação física.</p><button type="button" disabled>Velocidade 1</button><button type="button" disabled>Velocidade 2</button><button type="button" disabled>Velocidade 3</button><button class="vent-stop" type="button" disabled>Desligar</button><p>Protótipo somente com LEDs.</p></div><p>Esta é uma prévia estática da organização da tela, não uma execução Android. Os nomes e textos seguem a configuração do projeto .aia.</p>'''+figure('protocolo-estados','Estados e falhas do aplicativo com checkpoint 3.','Diagrama conceitual do protocolo: confirmação lógica e reenvio de 0 sem renovar o prazo; não é captura do editor.')+checklist('aluno-app','Verificação do aplicativo',['Os quatro comandos usam SendText com os caracteres corretos.','A conexão envia 0 e aguarda sua confirmação antes de liberar velocidades.','Ausência de confirmação, permissão negada e erro encerram o enlace.','O texto da interface distingue confirmação lógica de movimento físico.','Registrei separadamente importação, Companion e APK; não marquei testes que não fiz.'])+checkpoint('O app perdeu a conexão. Por que o próprio Arduino também precisa tratar a ausência de mensagens?','Porque um aviso na tela não altera, por si só, uma saída física. Na bancada, a supervisão do checkpoint 3 fornece um comportamento local demonstrável; a potência exige outras proteções.')
body7='''<div class="vent-alerta"><strong>Etapa pendente de profissional e equipamento.</strong> Não há circuito de 220 V executável nesta versão. O objetivo final continua sendo um ventilador real de 220 V com três velocidades.</div><p>Os LEDs permitiram testar intenção, comunicação e seleção. O novo limite é que o motor tem características elétricas, mecânicas e de falha que o LED não representa. Não substitua os LEDs por entradas de relés para “terminar” a montagem.</p><h3>Dossiê necessário para prosseguir</h3>'''+table(['Evidência','Quem precisa validar'],[('Identificação e estado do ventilador, manual e placa','Responsável técnico e proprietário do equipamento.'),('Esquema real de velocidades, motor, capacitor e proteção térmica','Profissional competente para a intervenção.'),('Dispositivos de manobra adequados ao motor e à partida','Responsável pelo dimensionamento.'),('Intertravamento independente, contato colado e falhas de alimentação','Responsável pelo projeto e ensaios.'),('Isolamento, invólucro, fiação, fixação e desconexão','Responsável pela instalação e inspeção.'),('Procedimentos e resultados de ensaios aplicáveis','Responsável pela liberação da etapa.')])+'''<p>O aplicativo permanece simples. As decisões profissionais devem ficar em uma documentação separada por modelo de ventilador. Trocar o equipamento pode exigir refazer essa documentação e o circuito de potência, mesmo mantendo o aplicativo.</p>'''+checkpoint('Se a simulação e os LEDs passaram em todos os testes, o que ainda falta para o ventilador?','Identificar o equipamento, projetar potência e proteções, validar falhas e executar inspeções e ensaios reais. A aprovação digital do conteúdo não substitui essas tarefas.')
body8='''<p>Concluir significa conseguir explicar o sistema e mostrar evidências. Separe o que foi analisado em código, observado no simulador, executado na bancada e inspecionado profissionalmente.</p>'''+table(['Teste','Resultado esperado','Ambiente'],[('0 e estados 1–3','Nenhum LED ou somente o LED escolhido.','Simulador e bancada.'),('12 trocas e repetição de comandos','Seleção coerente, sem dois LEDs acesos.','Programa e bancada.'),('Caractere inválido','Estado lógico 0.','Programa e bancada.'),('Reset e retorno da alimentação','Inicia com os LEDs apagados.','Placa física.'),('Ausência de supervisão no checkpoint 3','Apaga; “?” sozinho não religa.','Simulador e HC-05.'),('Permissão negada, falha e reconexão','Informa a falha; reconecta enviando 0.','Android real.'),('Motor e proteções','Critérios e ensaios definidos no projeto específico.','Somente etapa profissional.')])+checklist('avaliacao','Avaliação de aprendizagem',['Expliquei o percurso toque → texto → enlace → interpretação → saída.','Diferenciei bobina, contato e capacidade de comutação.','Entreguei esquema de LEDs coerente com o sketch usado.','Registrei ambiente, versão e resultado de cada teste realizado.','Listei as pendências de HC-05, módulo de relés, Android e potência.'])+'''<div data-vent-quiz data-explicacao="O retorno informa o estado lógico aplicado pelo programa; não mede a rotação."><h3>Uma última decisão</h3><p>O Arduino respondeu “3”. Qual afirmação é sustentada?</p><div class="vent-controles"><button type="button" data-correto="true">O programa confirmou o estado lógico 3</button><button type="button">O motor está fisicamente girando na alta</button></div><p role="status" class="vent-feedback"></p></div>
<h3>Entrega</h3><p>Apresente os arquivos usados, o registro dos testes e sua explicação sobre as falhas. Identifique no relatório o que ainda depende de componente, teste ou profissional. As marcações desta página são pessoais e não alteram o progresso global do Meu MbB.</p><p><a href="../downloads/ventilador/README.md" download>Baixar orientações e limites dos checkpoints</a> · <a href="../downloads/ventilador/VentiladorMBB.aia" download>Projeto App Inventor experimental</a></p>'''+checkpoint('O que você consegue demonstrar agora que não conseguia no começo?','Uma seleção de estados comandada por mensagens, a diferença entre os papéis dos componentes, uma política de supervisão de bancada e os limites que impedem extrapolar o protótipo para a rede elétrica.')
bodies=[body1,body2,body3,body4,body5,body6,body7,body8]
objs=['Explicar o percurso de um comando e os limites da versão de bancada.','Relacionar grandezas, proteções e responsabilidades ao projeto.','Prever o contato ideal e reconhecer o que falta do módulo real.','Distinguir pareamento, enlace e dado recebido.','Selecionar três indicadores e testar a supervisão de comunicação.','Montar uma interface com envio de texto e tratamento básico de falhas.','Identificar as evidências exigidas antes de qualquer potência.','Entregar evidências de aprendizagem e testes sem confundir os ambientes.']
